mapper.select:
SELECT id, belong_plate belongPlate, role_type roleType, menu_name menuName, update_time updateTime, publish_status publishStatus FROM t_operate_instructions where is_valid = 1
AND menu_code = #{query.menuCode}
AND role_type = #{query.roleType}
AND update_time >= #{query.startTime} AND update_time <= #{query.endTime}
order by update_time desc
